/**
 * GingerLive MCP server — Phase P0 (read-only).
 *
 * A Cloudflare Worker (Agents SDK `McpAgent`, Streamable HTTP at /mcp) that lets any
 * connected AI assistant query GingerLive's public offering. All answers come from a
 * static snapshot (src/data/agent-data.json) generated by the same pipeline that
 * builds llms.txt, so the tools
 * can never drift from the site or expose anything non-public. No auth, no writes in
 * P0 — a campaign-brief write path and OAuth are planned.
 */
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { McpAgent } from "agents/mcp";
import { registerGingerLive, SERVER_VERSION } from "./server";

interface Env {
  GINGERLIVE_MCP: DurableObjectNamespace;
}

export class GingerLiveMCP extends McpAgent<Env> {
  server = new McpServer({ name: "GingerLive", version: SERVER_VERSION });

  async init() {
    registerGingerLive(this.server);
  }
}

const HOME = `GingerLive MCP server.

Model Context Protocol endpoint (Streamable HTTP): /mcp
Health check: /health
SEP-1960 manifest: /.well-known/mcp
Registry card: /.well-known/mcp.json

Read-only tools: get_company_overview, get_network_stats, list_ad_formats,
list_case_studies, get_case_study, get_streamer_program_info.

Human-readable company facts: https://gingerlive.io/llms.txt
Developer resources: https://gingerlive.io/developers/
`;

const MCP_MANIFEST = {
  mcp_version: "1.0",
  server_version: SERVER_VERSION,
  endpoints: {
    streamable_http: "https://mcp.gingerlive.io/mcp",
  },
  capabilities: {
    tools: true,
    resources: true,
    prompts: true,
    sampling: false,
    roots: false,
  },
  authentication: {
    required: false,
    methods: [],
  },
  security: {
    tls_required: true,
    security_contact: "mailto:info@gingerlive.io",
  },
  registration: { dynamic: false },
  documentation: "https://gingerlive.io/developers/",
};

const jsonHeaders = {
  "content-type": "application/json; charset=utf-8",
  "x-content-type-options": "nosniff",
  "cache-control": "public, max-age=3600",
  "access-control-allow-origin": "*",
};

export default {
  fetch(request: Request, env: Env, ctx: ExecutionContext) {
    const url = new URL(request.url);

    if (url.pathname === "/health") {
      return Response.json({ status: "ok", server: "GingerLive", version: SERVER_VERSION });
    }

    if (url.pathname === "/.well-known/mcp" || url.pathname === "/.well-known/mcp.json") {
      return Response.json(url.pathname.endsWith(".json") ? {
        $schema: "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
        name: "io.gingerlive/mcp",
        title: "GingerLive",
        description: "GingerLive livestream ad formats, network reach stats, campaign case studies, and streamer program.",
        version: SERVER_VERSION,
        websiteUrl: "https://gingerlive.io",
        remotes: [{ type: "streamable-http", url: "https://mcp.gingerlive.io/mcp" }],
      } : MCP_MANIFEST, { headers: jsonHeaders });
    }

    if (url.pathname === "/" || url.pathname === "") {
      return new Response(HOME, { headers: { "content-type": "text/plain; charset=utf-8" } });
    }

    // Streamable HTTP transport (recommended for external clients).
    if (url.pathname === "/mcp" || url.pathname.startsWith("/mcp/")) {
      return GingerLiveMCP.serve("/mcp", { binding: "GINGERLIVE_MCP" }).fetch(request, env, ctx);
    }

    const problem = {
      type: "https://gingerlive.io/developers/#error-not-found",
      title: "Not Found",
      status: 404,
      detail: `No resource at ${url.pathname} on the GingerLive MCP host.`,
      code: "not_found",
      instance: url.pathname,
      hint: "Use POST/GET https://mcp.gingerlive.io/mcp (Streamable HTTP), GET /health, or GET /.well-known/mcp. Docs: https://gingerlive.io/developers/",
    };
    return new Response(JSON.stringify(problem, null, 2), {
      status: 404,
      headers: {
        "content-type": "application/problem+json; charset=utf-8",
        "x-content-type-options": "nosniff",
        "access-control-allow-origin": "*",
      },
    });
  },
};
